package deezer.android.app.data.mediasession.service;
import android.service.media.MediaBrowserService;import android.media.MediaMetadata;import android.media.session.*;import android.media.browse.MediaBrowser;import android.net.Uri;import android.os.*;import java.util.*;
public final class DeezerSdkMediaService extends MediaBrowserService{
 MediaSession session;
 public void onCreate(){super.onCreate();session=new MediaSession(this,"Flow fixture");session.setCallback(new MediaSession.Callback(){public void onPlayFromUri(Uri uri,Bundle extras){startService(new android.content.Intent(DeezerSdkMediaService.this,DeezerSdkMediaService.class));if(!"https://www.deezer.com/flow".equals(uri.toString()))throw new AssertionError("Wrong Flow URI");session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,"Background Flow").putString(MediaMetadata.METADATA_KEY_ARTIST,"Flow test").putLong(MediaMetadata.METADATA_KEY_DURATION,180000).build());session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY_FROM_URI|PlaybackState.ACTION_PAUSE).setState(PlaybackState.STATE_PLAYING,0,1).build());session.setActive(true);android.util.Log.i("FlowFixture","Background URI received without an Activity");}});session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY_FROM_URI).setState(PlaybackState.STATE_NONE,0,0).build());setSessionToken(session.getSessionToken());session.setActive(true);}
 public int onStartCommand(android.content.Intent intent,int flags,int id){android.app.NotificationManager nm=getSystemService(android.app.NotificationManager.class);nm.createNotificationChannel(new android.app.NotificationChannel("flow","Flow",2));startForeground(1,new android.app.Notification.Builder(this,"flow").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("Flow fixture").build());return START_STICKY;}
 public BrowserRoot onGetRoot(String pkg,int uid,Bundle hints){return new BrowserRoot("root",null);}
 public void onLoadChildren(String parent,Result<List<MediaBrowser.MediaItem>> result){result.sendResult(Collections.emptyList());}
 public void onDestroy(){session.release();super.onDestroy();}
}